X0,X1,Y0,Y1 = 14,50,8,40
W=X1-X0; H=Y1-Y0
grid=[['.']*W for _ in range(H)]
def mark(x0,y0,w,h,ch):
    for yy in range(int(y0),int(y0)+h):
        for xx in range(int(x0),int(x0)+w):
            if X0<=xx<X1 and Y0<=yy<Y1:
                grid[yy-Y0][xx-X0]=ch
sym={'transport-belt':'=','pipe':'p','pipe-to-ground':'P','inserter':'i','long-handed-inserter':'l','burner-inserter':'b','small-electric-pole':'o','medium-electric-pole':'O','iron-chest':'c','wooden-chest':'c','stone-furnace':'F','steel-furnace':'S','assembling-machine-1':'A','assembling-machine-2':'B','oil-refinery':'R','chemical-plant':'C','storage-tank':'T','pumpjack':'J','lab':'L','gun-turret':'G','electric-mining-drill':'D','boiler':'K','steam-engine':'E','splitter':'s','underground-belt':'u','offshore-pump':'W'}
cx=(X0+X1)/2; cy=(Y0+Y1)/2; R=max(W,H)/2*1.42
ents = get_entities(position=Position(x=cx,y=cy), radius=R)
for e in ents:
    n=e.name
    if n=='belt-group':
        for b in e.belts: mark(b.position.x-0.5,b.position.y-0.5,1,1,'=' if b.name=='transport-belt' else 'u')
        continue
    if n=='pipe-group':
        for b in e.pipes: mark(b.position.x-0.5,b.position.y-0.5,1,1,'p' if b.name=='pipe' else 'P')
        continue
    if n=='electricity-group':
        for b in e.poles: mark(b.position.x-0.5,b.position.y-0.5,1,1,'O' if 'medium' in b.name else 'o')
        continue
    try:
        w=int(e.tile_dimensions.tile_width); h=int(e.tile_dimensions.tile_height)
    except Exception:
        w=1;h=1
