def belts_at(cx,cy,r):
    out=[]
    for g in get_entities({Prototype.TransportBelt, Prototype.UndergroundBelt}, position=Position(x=cx,y=cy), radius=r):
        try:
            for b in g.belts:
                inv = b.inventory
                out.append("(%.1f,%.1f)%s L%s R%s" % (b.position.x,b.position.y,str(b.direction)[10:11], str(inv.get('left',''))[10:40], str(inv.get('right',''))[10:40]))
        except Exception as ex:
            out.append('x'+str(ex)[:40])
    return out
